function material(B,scene){const m=new B.StandardMaterial('field87-dirt',scene),t=new B.DynamicTexture('field87-soil-4m',256,scene,true),c=t.getContext(),im=c.createImageData(256,256);let seed=871;for(let i=0;i<im.data.length;i+=4){seed=(1664525*seed+1013904223)>>>0;const n=(seed/4294967296-.5)*9;im.data[i]=178+n;im.data[i+1]=156+n;im.data[i+2]=113+n;im.data[i+3]=255;}c.putImageData(im,0,0);t.update();t.wrapU=t.wrapV=B.Texture.WRAP_ADDRESSMODE;t.anisotropicFilteringLevel=8;m.diffuseTexture=t;m.specularColor=B.Color3.Black();return m;}
